      Z(4)=Z(4) + Z(5) - Z(9)
      Z(4)=Z(4)*Z(347)
      Z(3)=2*Z(4) + Z(3)
      Z(3)=iPq*Z(3)*t**3
      Z(2)=Z(2) + Z(3)
      Z(2)=iPq*iys*Z(2)
      Z(2)=Z(6) + Z(2)
      Z(2)=iPq*Z(2)
      Z(2)=Z(13) + Z(2)

      W(6) = iPq*Z(2)

END SUBROUTINE dlg_d_inB_intA_NDD_chch
